// Generated by TyraX. Do not edit - regenerated on every build.
// A copy of the editor's own VU framework source; change it there.
// Writing a VU1 microprogram in C++ (docs/vu-framework.md).
//
// The engine's VU1 programs are twenty near-identical .vclpp files: the same
// skeleton (load per-mesh constants, xtop the double buffer, emit the GIF tag
// block, loop over vertex triples, xgkick) around a small per-vertex body that
// differs by which attributes the mesh carries. Every feature added since -
// hardware fog, the in-band ALPHA tag, the spot light, the matcap - had to be
// threaded through all of them BY HAND, and each program's EE-side twin
// (unpack layout, maxVertCount, the GIF register list, the NLOOP patch offset)
// had to be kept in step by hand as well. That duplication, not the VU
// instruction set, is what makes this code hard to touch.
//
// So: describe a program once, in C++, and generate BOTH sides from it.
//
//   Desc d = descAsIsTextureColor();
//   Built b = build(d);            // b.program (IR), b.vclpp, b.eeSource, ...
//
// The backend emits VCL - NOT raw microcode. VCL still does the register
// allocation and the dual-issue scheduling, which is the whole reason a
// generated program is as fast as a handwritten one: it goes through the same
// optimizer, from source it would have accepted anyway. The framework never
// tries to out-schedule it.
//
// And because `Built::program` is the same `vuir::Program` the parser produces
// from the handwritten file, `equivalence()` can run BOTH in the host simulator
// on identical randomized input and diff the GS output bit for bit. That is the
// claim this module is built to support, and it needs no PS2 to check.
//
// No GL, no ImGui, no project.hpp - the aobake/livedbg shape.
#pragma once

#include <cstdint>
#include <string>
#include <vector>

#include "vuir.hpp"

namespace vugen {

// ---------------------------------------------------------------------------
// The builder
// ---------------------------------------------------------------------------

/** A value living in a virtual VF register. Registers are unlimited here; VCL
 * allocates the real 32 when it compiles the emitted source. */
struct Val {
    int16_t reg = 0;
    uint8_t bc = vuir::kNoBc;  // reading this value splats the named field
    Val broadcast(int field) const { return Val{reg, (uint8_t)field}; }
};

/** A value in a virtual integer register. */
struct IVal {
    int16_t reg = 0;
};

/** A branch target. Bind it with `Vu::bind` - forward branches are fine. */
struct Lbl {
    int id = -1;
};

class Vu {
   public:
    explicit Vu(vuir::Program& program);

    /** A number unique to THIS builder, for as long as the process runs.
     * Successive build() calls put their Vu at the same stack address, so a
     * pointer cannot tell "the same program" from "the next one" - and a
     * vu::Vec kept in a member across programs needs exactly that answer. */
    int id() const { return id_; }

    // --- registers -------------------------------------------------------
    Val named(const std::string& name);   // a stable, readable name
    IVal inamed(const std::string& name);
    Val tmp(const char* hint = "t");      // a fresh short-lived register
    Val zero() const { return Val{vuir::kVf00, vuir::kNoBc}; }
    IVal izero() const { return IVal{vuir::kVi00}; }

    // --- memory ----------------------------------------------------------
    Val lq(IVal base, int offset, uint8_t mask = vuir::MALL, const char* hint = "t");
    /** A per-mesh constant, addressed off vi00. */
    Val lqConst(int address, uint8_t mask = vuir::MALL, const char* hint = "k");
    void sq(Val value, IVal base, int offset, uint8_t mask = vuir::MALL);
    IVal ilw(IVal base, int offset, int field, const char* hint = "n");
    void isw(IVal value, IVal base, int offset, int field);

    // --- float arithmetic -------------------------------------------------
    Val add(Val a, Val b, uint8_t mask = vuir::MALL);
    Val sub(Val a, Val b, uint8_t mask = vuir::MALL);
    Val mul(Val a, Val b, uint8_t mask = vuir::MALL);
    Val minimum(Val a, Val b, uint8_t mask = vuir::MALL);
    Val maximum(Val a, Val b, uint8_t mask = vuir::MALL);
    Val move(Val a, uint8_t mask = vuir::MALL);
    /** acc = a * b (mula). */
    void mulAcc(Val a, Val b, uint8_t mask = vuir::MALL);
    /** acc += a * b (madda). */
    void maddAcc(Val a, Val b, uint8_t mask = vuir::MALL);
    /** dst = acc + a * b (madd), writing INTO `dst`. */
    void maddInto(Val dst, Val a, Val b, uint8_t mask = vuir::MALL);
    /** dst = acc - a * b (msub). */
    void msubInto(Val dst, Val a, Val b, uint8_t mask = vuir::MALL);
    /** loi - loads the I register. Ops taking `useI` read it. */
    void loadI(float value);
    Val minimumI(Val a, uint8_t mask = vuir::MALL);
    Val addI(Val a, uint8_t mask = vuir::MALL);
    /** q = a[fa] / b[fb]. */
    void divQ(Val a, int fa, Val b, int fb);
    void rsqrtQ(Val a, int fa, Val b, int fb);
    Val mulQ(Val a, uint8_t mask = vuir::MALL);
    Val ftoi4(Val a, uint8_t mask = vuir::MALL);
    Val ftoi0(Val a, uint8_t mask = vuir::MALL);
    /** In-place variants, for when the handwritten macro overwrote its input
     * (the emitted code must match instruction for instruction to stay
     * bit-identical, and an extra `move` would not). */
    void ftoi4Into(Val dst, Val a, uint8_t mask = vuir::MALL);
    void ftoi0Into(Val dst, Val a, uint8_t mask = vuir::MALL);
    void mulInto(Val dst, Val a, Val b, uint8_t mask = vuir::MALL);
    void addInto(Val dst, Val a, Val b, uint8_t mask = vuir::MALL);
    void subInto(Val dst, Val a, Val b, uint8_t mask = vuir::MALL);
    void absInto(Val dst, Val a, uint8_t mask = vuir::MALL);
    /** 1.0 in every field, from vf00 alone - two instructions, no `loi`. A
     * broadcast is only legal on the SECOND operand of a VU instruction, so
     * `vf00[w]` cannot stand in for it wherever the 1.0 has to come first. */
    void onesInto(Val dst);
    void minimumIInto(Val dst, Val a, uint8_t mask = vuir::MALL);
    void minimumInto(Val dst, Val a, Val b, uint8_t mask = vuir::MALL);
    void maximumInto(Val dst, Val a, Val b, uint8_t mask = vuir::MALL);
    void mulQInto(Val dst, Val a, uint8_t mask = vuir::MALL);

    // --- integer ----------------------------------------------------------
    IVal iadd(IVal a, IVal b, const char* hint = "i");
    void iaddInto(IVal dst, IVal a, IVal b);
    IVal iaddiu(IVal a, int imm, const char* hint = "i");
    void iaddiuInto(IVal dst, IVal a, int imm);
    IVal ior(IVal a, IVal b, const char* hint = "i");
    IVal iand(IVal a, IVal b, const char* hint = "i");
    IVal mtir(Val a, int field, const char* hint = "i");

    /** Where the next instruction will land, and a way to MOVE a run of them
     * somewhere earlier. A script builds its constants with the same calls the
     * body uses, but a constant belongs in the PREAMBLE: emitting loi inside
     * the per-vertex body gives vcl a run of I-register writes to schedule
     * around, and what comes out on hardware is not what the simulator ran. */
    int mark() const;
    /** Move [from, end) to index . Returns how many instructions moved. */
    int hoist(int from, int to);

    // --- control ----------------------------------------------------------
    /** `name` becomes the label in the emitted source - generated microcode
     * gets debugged on hardware, so it should read like the handwritten kind. */
    Lbl label(const char* name);
    void bind(Lbl l);
    void branch(Lbl l);
    void branchIfLez(IVal a, Lbl l);
    void branchIfNotEq(IVal a, IVal b, Lbl l);
    void branchIfEq(IVal a, IVal b, Lbl l);
    void branchIfGtz(IVal a, Lbl l);
    void branchIfLtz(IVal a, Lbl l);

    // --- the clip family's own primitives ---------------------------------
    // Only the CLIP programs need these: the cull and as_is families judge a
    // vertex through fogClipCheck, which bundles clipw+fcand for the one
    // question they ask. A clipper asks several different questions of the
    // same instruction pair, so it needs them apart.
    /** Copy, field-masked. `add dst, vf00, src` would cost the same and read
     * worse; the handwritten programs use `move` and so does this. */
    void moveInto(Val dst, Val a, uint8_t mask = vuir::MALL);
    /** Judge xyz against +/-w, setting the clip flags. Reads the register's
     * OWN w, which is why the callers rewrite w before each use. */
    void clipwInto(Val a, uint8_t mask = vuir::MXYZ);
    /** Read the clip flags. NOTE the semantics the handwritten programs rely
     * on: fcand sets its destination to 0 or 1 - "any masked bit set" - and
     * NOT to the bit pattern. Every judgement is written to be read that
     * way. */
    void fcandInto(IVal dst, int mask);
    void iorInto(IVal dst, IVal a, IVal b);
    void iandInto(IVal dst, IVal a, IVal b);
    void isubInto(IVal dst, IVal a, IVal b);
    void xtop(IVal dst);
    void xgkick(IVal address);
    /** VCL scheduling markers, reproduced so the emitted source matches the
     * shape the handwritten programs use around XGKICK. */
    void barrier();
    void cont();

    // --- the method library the framework offers --------------------------
    /** ScaleVertexToGSFormat: NDC -> the GS 12.4 screen format, in place.
     * acc = scale * 1.0; v = acc + v * scale; v = ftoi4(v)  (xyz only, so the
     * clip-space W survives for fog and the perspective divide). */
    void scaleToGsFormat(Val vertex, Val scale);
    /** FixColor: clamp to 0..255 and convert to integer bits, in place. */
    void fixColor(Val color);
    /** CalculateTyraFog: the GS fog coefficient from the vertex's clip W,
     * already shifted into the F field position of a packed XYZF2. */
    /** `dst` and `scratch` are supplied by the caller and REUSED across the
     * three vertices on purpose. Minting a fresh register per call is what a
     * value-returning API wants to do, and it is a trap here: VU1 has 16
     * integer registers, the simulator has unlimited virtual ones, so the
     * pressure is invisible to `--vu-check` and only shows on hardware. */
    void fogCoefficient(IVal dst, Val vertex, Val fogParams, Val scratch);
    /** MatrixMultiplyVertex: dst = m * v, the four-register mula/madd chain. */
    void transform(Val dst, const Val m[4], Val v);
    /** CalculateTyraDirectionalLights: three directional lights plus ambient,
     * from an OBJECT-space normal. `normal` is overwritten with its world-space
     * self on the way (the handwritten macro does the same), and the alpha is
     * set to the GS "1.0" of 128 because a lit mesh carries no colour stream. */
    void dirLightShade(Val color, Val normal, const Val lightMatrix[3],
                       const Val lightDirs[3], const Val lightColors[3],
                       Val ambient);
    /** ResetClipFlags: clear the clip-flag shift register before the loop. */
    void resetClipFlags();
    /** MakeTyraAdcMask: build the 0x8000 ADC bit once (iaddiu immediates are
     * 15-bit, so it takes two adds). */
    void makeAdcMask(IVal dst);
    /** VertexPersCorr: the perspective divide, xyz only so the clip-space W
     * survives. WRITES Q. */
    void persCorrect(Val dst, Val v);
    /** PerformTyraFogClipCheck: the frustum test whose verdict rides in the ADC
     * bit of the vertex's W word, with the fog coefficient OR-ed in beside it.
     * `judge` and `adcBit` are caller-owned scratch (see fogCoefficient on why
     * these are not minted per call). */
    void fogClipCheck(Val vertex, IVal destAddress, int offset, IVal fogInt,
                      IVal adcMask, IVal adcBit);
    /** CalculateTyraSpotLight: the flashlight cone, added onto the baked vertex
     * colour. Runs on the OBJECT-space vertex, so it must come before the MVP
     * multiply. `scratch` supplies seven temporaries. */
    void spotLight(Val color, Val vertex, Val spotPos, Val spotDir, Val spotCol,
                   const Val scratch[7]);
    /** Builds a register holding four different literals, one per field, so a
     * body that needs constants reads them as broadcasts instead of spending a
     * `loi` per use. Costs eight instructions ONCE, in the preamble. */
    void constants(Val dst, float x, float y, float z, float w);
    /** sin(angle), to about 0.2% - the parabolic approximation with one
     * correction term, which is what a per-vertex effect needs and a Taylor
     * series is not (it needs range reduction to converge and the VU has no
     * cheap one).
     *
     * `phase` is the quarter-turn offset added to t: pass `kc[y]` (0.5) for a
     * sine and a literal 0.75 for a COSINE. Adding pi/2 to the angle instead
     * looks equivalent and is not - pi/2 is not exactly a quarter turn in
     * float, so cos(0) comes back as 1 - 6e-8 and a "rotate by zero" stage
     * stops being the identity. Phasing t is exact at every quarter turn.
     *
     *   t  = angle/2pi + phase
     *   u  = t - floor(t)                floor via the 2^23 add/sub trick
     *   x  = 2u - 1                      in [-1,1), so angle = pi*x
     *   y  = 4x(1-|x|)                   ~= sin(pi x), 5.6% error
     *   r  = y + 0.225*(y|y| - y)        ~= sin(pi x), 0.2% error
     *
     * `kc` must be `constants(1/2pi, 0.5, 8388608.0, 0.225)` and `one` a
     * register whose fields are 1.0. `scratch` supplies three temporaries, and
     * they are the CALLER's - see fogCoefficient on why. Seventeen
     * instructions, and it runs on whichever fields `mask` selects, so three
     * components cost the same as one. */
    void sineApprox(Val dst, Val angle, uint8_t mask, Val kc, Val one,
                    const Val scratch[3], Val phase);
    /** Truncate toward zero, componentwise - `trunc` is two instructions on the
     * VU (ftoi0 then itof0) and several stages want it. */
    void truncate(Val dst, Val a, uint8_t mask);
    /** CalculateTyraEnvStq: turns the object-space normal carried in the ST
     * slot into a sphere-map (matcap) ST, in place.
     *   s = 0.5 + 0.5 * dot(normalize(n), cameraRight)
     *   t = 0.5 - 0.5 * dot(normalize(n), cameraUp)
     * The normal is RE-NORMALIZED first because the EE clipper lerps it across
     * clip cuts and a lerped normal is short. That costs an rsqrt, which WRITES
     * Q - so this must run BEFORE the position's perspective divide, or the
     * later mulq picks up the wrong Q. The EE uploads a transposed, pre-scaled
     * basis so both dot products share one accumulator chain; `scratch`
     * supplies only the length and normalized-vector temporaries. */
    void envStq(Val stq, Val envBasisX, Val envBasisY, Val envBasisZ,
                const Val scratch[2]);

   private:
    vuir::Program* p_;
    int id_ = 0;
    int tmpSeq_ = 0;
    std::vector<int> labelIndex_;                    // label id -> code index
    std::vector<std::string> labelNames_;            // label id -> emitted name
    std::vector<std::pair<int, int>> fixups_;        // code index -> label id
    friend struct Finisher;
    void emit(vuir::Instr in);

   public:
    /** Resolves forward branches. Call once, after the body is built. */
    void finish();
};

// ---------------------------------------------------------------------------
// Stages - the authoring layer (docs/vu-authoring.md)
// ---------------------------------------------------------------------------

/** Where in the chain a stage runs. The slot is the whole of what a stage
 * author has to understand about the pipeline, which is why it is an enum with
 * five entries rather than a hook system. */
enum class Slot : uint8_t {
    /** On the OBJECT-space position, before the MVP multiply. The only place
     * geometry means anything a modeller would recognise, and the only place a
     * displacement is in the mesh's own units. Also the last point where the
     * colour and the untransformed position are both in hand. */
    ObjectSpace,
    /** On the CLIP-space position (xyzw), after the MVP multiply and before the
     * perspective divide. For depth work: w is the view distance. */
    ClipSpace,
    /** On the NDC position, after the perspective divide and before the scale
     * into the GS 12.4 screen format. Screen-space effects live here. */
    Ndc,
    /** On the vertex COLOUR, before FixColor clamps it to 0..255. */
    Color,
    /** On the ST, right after it is loaded and before the perspective
     * correction. Textured bases only. */
    Texture,
    /** A VU0 kernel's element body - see KernelDesc. Not a StaPip slot. */
    Kernel,
};

const char* slotName(Slot s);

struct StageParamDef {
    const char* name = "";
    const char* tip = "";
    float def = 0.0f;
    float lo = 0.0f;
    float hi = 1.0f;
    /** A literal-only parameter cannot be bound to a per-mesh slot: the
     * generator needs its value at build time (a reciprocal it folds, a count
     * it unrolls). Say so instead of silently ignoring the binding. */
    bool literalOnly = false;
    /** This parameter is the stage's STRENGTH. When every strength parameter of
     * a stage is the literal 0 the stage is not emitted at all - which is what
     * makes "leave it in the list at zero" free rather than merely harmless. */
    bool strength = false;
};

struct StageDef {
    const char* key = "";     // stable id, serialized
    const char* title = "";   // what the panel shows
    Slot slot = Slot::ObjectSpace;
    const char* desc = "";
    int paramCount = 0;
    StageParamDef params[4];
    bool needsTime = false;     // reads the animation clock
    bool needsTexture = false;  // textured base only
    /** Emitted instructions per vertex, measured by building the stage alone.
     * A budget number, not a cycle count - VCL still pairs what it can. */
    int perVertex = 0;
    /** Legal inside a VU0 kernel. A kernel element is one quadword and
     * nothing else: a stage that reads a colour or an ST has nothing to read,
     * so it is REFUSED rather than silently reinterpreted. */
    bool kernelSafe = false;
    /** This stage MOVES the geometry. It matters beyond the obvious because an
     * object is drawn by more than one bag and those bags are not all in the
     * same material class: a baked lightmap pass carries the AO ATLAS, so it is
     * a TEXTURED bag even on an untextured mesh. Displace one and not the other
     * and the lightmap stays behind as a ghost of the undeformed shape - which
     * is what it looked like on the console. */
    bool movesGeometry = false;
    /** How many of `StageCtx::s[]` this stage touches. The scratch pool is
     * allocated to the largest any PLANNED stage needs, not to the largest any
     * stage could need - three spare registers is a real cost when the sine's
     * own three are on top and VCL only has 31. */
    int scratch = 1;
};

/** The catalogue. Ordered by slot, then by how often you would reach for it. */
const std::vector<StageDef>& stageDefs();
/** nullptr when the key names nothing - an unknown stage is DROPPED rather
 * than guessed at, the readFlowGraph rule. */
const StageDef* stageDef(const std::string& key);

/** One authored parameter value: a literal, or field `meshSlot` of the per-mesh
 * quadword the game uploads (VU1_CUSTOM_PARAMS_ADDR). */
struct StageParam {
    float value = 0.0f;
    int meshSlot = -1;  // -1 = the literal above; 0..3 = x/y/z/w of the quad
    bool operator==(const StageParam& o) const {
        return value == o.value && meshSlot == o.meshSlot;
    }
};

struct Stage {
    std::string key;
    bool enabled = true;
    StageParam params[4];
    bool operator==(const Stage& o) const {
        if (key != o.key || enabled != o.enabled) return false;
        for (int i = 0; i < 4; ++i)
            if (!(params[i] == o.params[i])) return false;
        return true;
    }
};

/** A stage list with its defaults filled in - what the panel edits. */
Stage makeStage(const std::string& key);

/** True when the stage would emit nothing: disabled, unknown, or every
 * strength parameter is a literal zero. */
bool stageIsNoOp(const Stage& s);

/** True when any live stage of the list DISPLACES geometry. Worth asking about
 * a whole list because of what it implies elsewhere: an object is drawn by
 * several bags and they are not all in the same material class - a baked
 * lightmap pass carries the AO atlas, so it is a TEXTURED bag even on an
 * untextured mesh. Move one and not the other and the lightmap stays behind. */
bool stagesMoveGeometry(const std::vector<Stage>& stages);

// ---------------------------------------------------------------------------
// Program descriptions
// ---------------------------------------------------------------------------

/** One StaPip "as is" program - the family the EE clipper feeds, i.e. positions
 * that are ALREADY in NDC with the clip-space W kept for fog and for the texture
 * perspective divide. */
/** Everything a project's own C++ script is handed. These are the SAME
 * registers the built-in stages get - the position in whatever space the slot
 * says, the mesh's colour, its ST, its four numbers and the clock - so a script
 * is not a second-class citizen of the generator, it is the same citizen with
 * the body written by someone else.
 *
 * The scratch registers are the caller's, and that is not a detail: VU1 has 32
 * float registers, VCL allocates 31 of them, and a script that minted its own
 * per value would push the allocation over a cliff that is INVISIBLE on the
 * host - it shows up as `no opt table` from vcl, inside Docker, with no line
 * number. (docs/vu-authoring.md, "The other ceiling".) */
struct ScriptCtx {
    Vu* b = nullptr;
    Val position{};  // the vertex, in the space the script's slot names
    Val color{};     // vertex colour, 0..255 per channel in the GS sense
    Val st{};        // texture coordinates, only when hasSt
    Val params{};    // the object's four numbers (SceneObjectData::vuParams)
    Val time{};      // (seconds, sin, cos, 1.0) - already range-reduced
    Val one{};       // 1.0 in every field
    Val normal{};    // OBJECT-space normal, only on a class that carries one
    Val scratch[8];  // as many as Desc::scriptScratch asked for
    /** Where a script's CONSTANTS belong: the preamble, which runs once per
     * buffer instead of once per vertex. vu::splat and friends emit into the
     * body and then hoist the run back to here. */
    int preambleAt = 0;
    bool hasColor = false;
    bool hasSt = false;
    bool hasNormal = false;
};

/** The body of a project's script. One call per VERTEX, three times per
 * triangle - the loop, the packet and the GIF tag are the framework's. */
using ScriptFn = void (*)(ScriptCtx&);

struct Desc {
    std::string vclName;      // #vuprog name, e.g. "StaPipVU1AsIsTC"
    std::string asmName;      // .name / linker symbol stem, "StaPipVU1As_Is_TC"
    std::string fileStem;     // "stapip_as_is_tc_vu1"
    std::string className;    // "StaPipAsIsTCVU1Program"
    std::string programEnum;  // "StaPipAsIsTextureColor"
    std::string title;        // human label, "StaPip - As is - TC"
    bool texture = false;     // carries an ST stream
    bool dirLights = false;   // carries normals, shades on VU
    bool env = false;         // matcap: the ST slot holds an object-space normal
    /** The cull family: same skeleton, but the MVP multiply, the ADC frustum
     * test and the spot light run on VU1. Resident in BOTH clipping modes -
     * `as_is` is only uploaded with the EE clipper, `clip` only with VU1
     * clipping, so cull is the one family a custom program can build on and
     * still draw under the default settings. */
    bool cull = false;
    /** The CLIP family: replaces the EE clipper for frustum-crossing packages.
     * Like cull it does its own MVP multiply - so unlike as_is it still has the
     * object-space position, which is what lets a displacing script run on the
     * geometry the clipper produced. Emits a VARIABLE number of vertices and
     * patches the prim tag's NLOOP with the count. */
    bool clip = false;
    /** Built-in clip images can cover one ABI-compatible peer at run time:
     * C also covers D, and TC also covers TCE. The peer uses the same input
     * stride, scratch stride and GIF register list, so only the per-corner
     * shading branch differs; custom programs remain fully specialised. */
    bool sharedClipDir = false;
    bool sharedClipEnv = false;
    /** The image an EE wrapper actually UPLOADS for this program, as a
     * `.name`/linker symbol stem. Empty means the program owns its own image;
     * otherwise it names the ABI-compatible peer whose image covers this one,
     * and this description's own `.vclpp` is a REFERENCE - generated, checked
     * against the shared image's peer path, and never linked, because nothing
     * points at its symbols. Set on the ALIAS, never on the owner.
     *
     * The two flags above say "my body carries a peer's path too"; this says
     * "somebody else's body carries mine", and the emitter needs the second
     * fact rather than the first. Deriving it from the flags at the point of
     * emission is what shipped a D wrapper linking the D image - the sharing
     * silently undone, five images back in micro memory, and nothing to see in
     * a diff of the microcode. */
    std::string residentImageAsmName;
    /** `fileStem` of the description that owns that image, for callers that
     * work in descriptions rather than symbols (the budget, the panel). Empty
     * exactly when the field above is. */
    std::string codeOwner;
    /** Test-harness value written to VU1_OPTIONS_ADDR.y. It does not change
     * generated code; non-zero selects the shared image's peer path. */
    int runtimeClipVariant = 0;
    std::string dir = "as_is";  // sub-directory under programs/

    /** A PROJECT's own program: the same skeleton with a stage list woven in.
     * Only the cull family can carry one - it is the only family resident in
     * both clipping modes, and it is the only one that still has the
     * object-space position in hand (the as_is family is fed NDC by the EE
     * clipper, so there is nothing left to displace). */
    std::vector<Stage> stages;
    /** Set for a generated project program: changes the emitted file's header,
     * makes the preamble load the per-mesh parameter and time quadwords, and
     * stops `--vu-check` looking for a handwritten twin. */
    bool custom = false;

    /** A project's own C++ SCRIPT, woven in at the same points a stage is. The
     * stage list above is the shortcut for the common cases; this is the way
     * out of it - the script sees the same registers the catalogue does and
     * can do anything the builder can. Null unless the project wrote one. */
    ScriptFn script = nullptr;
    /** Run ONCE where the preamble ends. A script's constants belong there,
     * not three times over in an unrolled vertex loop. */
    ScriptFn scriptPrepare = nullptr;
    Slot scriptSlot = Slot::Color;
    /** Scratch registers the script asked for, on top of what the stages take.
     * The caller owns them for the same reason a stage does not mint its own:
     * VF pressure is invisible on the host. */
    int scriptScratch = 4;
};

/** The program a look replaces on one material class, as a
 * StaPipProgramClass bit (1<<0 colour, 1<<1 dirLights, 1<<2 textureDirLights,
 * 1<<3 textureColor, 1<<4 textureEnv). All five are available. The lighting
 * classes are usable as long as no stage binds a PER-MESH parameter - those
 * live in the directional-lights colour block, which a lit program needs
 * (project::vuClassCanBind).
 *
 * `half` picks which of the class's programs is meant. A class is TWO resident
 * programs at any moment: `Cull` draws a package wholly inside the frustum, and
 * one of the other two draws a package that crosses a plane - `AsIs` under the
 * EE clipper, `Clip` under VU1 clipping. An override has to replace the
 * resident PAIR or the props at the edge of the screen keep the stock shading,
 * and since the clipping mode is a run-time switch, replacing all three is what
 * makes an effect survive it. */
enum class Half : uint8_t { Cull, AsIs, Clip };
Desc descForClass(unsigned classBit, int lookIndex = 0,
                  Half half = Half::Cull);
/** The ENGINE's own description for one material class and half - the built-in
 * program a look replaces, with its aliasing intact. `descForClass` is this
 * lookup plus a project's naming, and it drops the aliasing because a look is
 * always its own image. Ask this one when the question is what the engine
 * uploads (the budget panel), not what a project generates. */
Desc engineDesc(unsigned classBit, Half half = Half::Cull);
/** Every class bit, low to high. */
const std::vector<unsigned>& customClasses();
/** "Untextured (vertex colour)", "Textured", ... - THE label for a class, used
 * by the panel, the inspector, the diagnostics and the generated file headers.
 * project::vuClassName forwards here. */
const char* classTitle(unsigned classBit);

/** The fifteen StaPip programs the engine ships: five `as_is` (fed by the EE
 * clipper) crossed with five `cull` (transform + frustum test on VU1), plus the
 * five `clip` programs that replace the EE clipper when VU1 clipping is on. A
 * material class is always TWO resident programs - cull for a package wholly
 * inside the frustum, and either as_is or clip for one that crosses. */
Desc descAsIsColor();
Desc descAsIsTextureColor();
Desc descAsIsDirLights();
Desc descAsIsTextureDirLights();
Desc descAsIsTextureEnv();
Desc descClipColor();
Desc descClipTextureColor();
Desc descClipDirLights();
Desc descClipTextureDirLights();
Desc descClipTextureEnv();
Desc descCullColor();
Desc descCullTextureColor();
Desc descCullDirLights();
Desc descCullTextureDirLights();
Desc descCullTextureEnv();
std::vector<Desc> allDescs();

/** The linker symbol stem an EE wrapper must reference for `d` - the owner's
 * when `d` aliases a peer's image, `d.asmName` otherwise. EVERY emitted
 * `extern u32 ..._CodeStart` goes through here. */
std::string residentImage(const Desc& d);
/** False when a peer's image covers `d`, i.e. `d` contributes no code of its
 * own to the ELF and nothing to the micro-memory budget. */
bool ownsResidentImage(const Desc& d);

/** Which twin draws a frustum-CROSSING package. It is a run-time switch
 * (`project::Vu1Clipping`), and the two modes hold different program sets, so
 * "does the set fit in micro memory" only has an answer per mode. */
enum class ClipMode : uint8_t { Vu1, Ee };
/** The built-in images resident in micro memory at once under `mode`, worst
 * case: one `cull` program per material class plus the crossing-half twin -
 * `clip` under VU1 clipping, `as_is` under the EE clipper - with aliased peers
 * dropped, because a shared image is uploaded ONCE (`Path1::
 * createProgramsCache`). A project that draws fewer material classes uploads a
 * subset (`StaPipQBufferRenderer::setResidentClasses`), and a look adds its own
 * images on top; both are the panel's job, not this one's. */
std::vector<Desc> residentSet(ClipMode mode);

/** Everything generated for one program. */
struct Built {
    vuir::Program program;   // simulate this
    std::string vclpp;       // the .vclpp source, ready for the Docker build
    std::string eeHeader;    // inc/.../<stem>_program.hpp
    std::string eeSource;    // src/.../<stem>_program.cpp
    int tagQuads = 0;        // GIF tag block, in quadwords
    int regsPerVertex = 0;   // GS registers per vertex (the store stride)
    int attrStreams = 0;     // per-vertex input arrays the EE unpacks
    std::vector<std::string> notes;
    /** What the stage list cost, MEASURED: the same description is built once
     * without its stages and the difference reported. Not a sum of the
     * catalogue's per-stage estimates, which would drift the moment a stage
     * folded a literal away. */
    int stageInstrs = 0;
    /** Stages that emitted nothing, and why (disabled, zero strength, unknown
     * key) - so "I added it and nothing happened" has an answer on screen. */
    std::vector<std::string> droppedStages;
    /** Non-empty means the description is not buildable as written: a stage on
     * a base that cannot carry it, a mesh binding on a baked parameter. */
    std::vector<std::string> errors;
};

Built build(const Desc& d);

// ---------------------------------------------------------------------------
// VU0 kernels - the second skeleton
// ---------------------------------------------------------------------------

/** A VU0 compute kernel: N quadwords in, N quadwords out, one stage list run
 * per element.
 *
 * Nothing about the VU1 skeleton survives here and that is the point. There is
 * no `xtop` (VIF0 is not double-buffered - the EE stores straight into VU0 data
 * memory at fixed addresses), no GIF tag block and no `xgkick` (VU0 has no path
 * to the GS), and no branch back to a buffer loop - a kernel ENDS, and the EE
 * re-enters it at instruction 0 with `vcallms` on the next call. Data memory
 * persists across those calls, so the parameter quadword is stored once and
 * only the batch changes.
 *
 * The size limit is real and small: 256 quadwords TOTAL. The default layout
 * below leaves room for 112 elements in and 112 out. */
struct KernelDesc {
    std::string vclName = "TyraXKernel";      // #vuprog name
    std::string asmName = "TyraXKernel";      // .name / linker symbol stem
    std::string fileStem = "vu0_kernel";      // <stem>.vclpp, <stem>_kernel.*
    std::string className = "TyraXVu0Kernel";  // the emitted EE driver
    /** What the emitted .cpp includes. Its own header travels to inc/ in a
     * generated project (a user script includes it, and inc/ is the only
     * directory on the game's include path), so the name cannot be derived
     * from fileStem. */
    std::string headerName = "vu0_kernel_kernel.hpp";
    std::string title = "TyraX VU0 kernel";

    /** Data-memory map, in quadwords. Defaults leave 112 elements each way
     * inside VU0's 256 - `build` refuses a layout that does not fit. */
    int controlAddr = 0;  // .x = element count for this call
    int paramAddr = 1;    // the four user parameters, as a quadword
    int inputAddr = 8;
    int outputAddr = 120;
    int maxElements = 112;

    /** Run per element. Stages see the element in the `vertex` role, so the
     * ObjectSpace geometry stages work unchanged; anything reading a colour or
     * an ST is not offered for a kernel. */
    std::vector<Stage> stages;

    /** A project's own C++ BODY, woven in exactly where the stage list is -
     * the `vu::Kernel` half of src/vushader.hpp. The stage list above is the
     * shortcut for what the catalogue happens to cover; this is the way out of
     * it, and it is the only way to compute something the catalogue does not
     * describe.
     *
     * Both may be set: the stages run first and the body sees what they left in
     * the element, the same order a script and a stage list share on VU1. */
    ScriptFn script = nullptr;
    /** Run ONCE, where the preamble ends - before the element loop. A kernel's
     * loop is a real branch rather than an unrolled run, so this matters more
     * here than on VU1: a constant built per element is rebuilt per element. */
    ScriptFn scriptPrepare = nullptr;
    /** Scratch registers the body asked for, on top of what the stages take.
     * Owned by the caller for the reason a stage's are - see Desc. */
    int scriptScratch = 4;
};

struct BuiltKernel {
    vuir::Program program;
    std::string vclpp;
    std::string eeHeader;
    std::string eeSource;
    std::vector<std::string> notes;
    std::vector<std::string> errors;  // non-empty = do not emit this
    int perElement = 0;               // emitted instructions inside the loop
};

BuiltKernel buildKernel(const KernelDesc& k);

/** Runs a built kernel on the host over `in` (4 floats per element) and returns
 * the output the same way, so the panel can show what a kernel does before
 * anything is built in Docker. `params` is the parameter quadword. */
std::vector<float> simulateKernel(const BuiltKernel& b, const KernelDesc& k,
                                  const std::vector<float>& in,
                                  const float params[4], float time,
                                  std::string* error);

// ---------------------------------------------------------------------------
// Checking
// ---------------------------------------------------------------------------

/** Result of running two programs on identical input and diffing what they
 * staged for the GS. */
struct Equivalence {
    bool ran = false;
    bool identical = false;
    std::string error;
    int trials = 0;
    int vertices = 0;
    int firstBadTrial = -1;
    std::string detail;      // what differed, when something did
    int handwrittenInstrs = 0;
    int generatedInstrs = 0;
};

/** Runs `a` and `b` over `trials` randomized vertex buffers (deterministic in
 * `seed`) and compares every quadword of the GIF packet each staged. This is
 * the framework's central check: not "the text looks similar" but "the bits the
 * GS would receive are the same". */
Equivalence equivalence(const vuir::Program& a, const vuir::Program& b,
                        const Desc& d, int trials, uint32_t seed,
                        const float customParams[4] = nullptr,
                        float customTime = 0.0f);

// ---------------------------------------------------------------------------
// Micro-memory budget
// ---------------------------------------------------------------------------

/** VU1 micro memory holds 2048 instruction slots, and `Path1` parks the
 * draw-finish helper at the very top - overwriting it hangs the post-fx PATH1
 * barrier forever (see path1.cpp). The pipeline set must fit below that. */
constexpr int kMicroMemSlots = 2048;
/** Measured headroom below the draw-finish helper. */
constexpr int kVu1MicroCeiling = 2042;
/** VU0 micro memory is 4 KB - 512 slots - and nothing is parked in it, so a
 * kernel gets all of them. The engine's raytracer kernel is 504 emitted
 * instructions, which is how close to that ceiling real VU0 code runs. */
constexpr int kVu0MicroCeiling = 512;

struct BudgetEntry {
    std::string name;
    int emitted = 0;   // instructions the framework emitted
    int slotsMin = 0;  // if VCL paired every one of them
    int slotsMax = 0;  // if it paired none
};

struct Budget {
    std::vector<BudgetEntry> entries;
    int totalMin = 0;
    int totalMax = 0;
    int ceiling = kVu1MicroCeiling;
    bool certainlyFits() const { return totalMax <= ceiling; }
    bool certainlyOverflows() const { return totalMin > ceiling; }
};

/** Instruction counts are a RANGE on purpose: VCL packs an upper and a lower op
 * into one 64-bit slot when it can, so N emitted instructions occupy between
 * ceil(N/2) and N slots. The exact number is only known after VCL runs - which
 * is why the engine's own guard is a runtime assert. Reporting the range is
 * honest; reporting a single number would not be. */
Budget budget(const std::vector<std::pair<std::string, const vuir::Program*>>& set,
              int ceiling = kVu1MicroCeiling);

// ---------------------------------------------------------------------------
// Register pressure
// ---------------------------------------------------------------------------

/** A VU has 32 float registers and `vf00` is hardwired, so 31 are allocatable.
 * The IR has UNLIMITED virtual ones and VCL does the allocation - which means
 * running out is invisible to every host check here and shows up as
 *
 *     ERROR: no opt table.. something failed making table .. for processing!
 *
 * from `vcl`, inside Docker, minutes later, with no line number. That is the
 * worst feedback in the whole toolchain, so it gets predicted instead. */
constexpr int kVfRegisters = 31;

struct Pressure {
    int peak = 0;             // most VF registers live at once (over-stated)
    int at = -1;              // instruction index where that happens
    int names = 0;            // distinct VF names the program uses
    std::vector<std::string> live;  // what is live at the peak, for diagnosis
    bool fits() const { return peak <= kVfRegisters; }
};

/** Peak simultaneous live VF registers, by the linear-scan approximation: each
 * register's live range is [first write, last read] and the peak is the most
 * ranges covering any one instruction.
 *
 * It OVER-STATES, and knowing by how much is the whole of its usefulness. A
 * register reused as scratch across three unrolled vertices has one long
 * [first, last] range here while being dead in between, and VCL splits live
 * ranges where this cannot. So it is an INDICATOR, calibrated against three
 * measurements rather than a rule:
 *
 *   <= 27   every one of the engine's ten resident programs, all of which
 *           compile - so this range is known-good
 *      32   a two-stage textured program: vcl allocated it fine
 *      36   a four-stage colour program: `no opt table`, build dead
 *
 * Treat past 31 as "vcl may refuse", not as "it will". It must not gate a
 * check: an over-stating estimate that turns a green run red is worse than no
 * estimate at all. */
Pressure vfPressure(const vuir::Program& p);

}  // namespace vugen
